### Describe the bug

All valid directive should be recognized as directive before first non directive.

```JavaScript
"foo";
"bar";

"use strict";
// ^ This is valid strict directive
function foo(a, a) {
  //         ^^^^ SyntaxError: Duplicate parameter name not allowed in strict context
}
```

### Input code

```typescript
"use client";
"foo";
"use bar"; // this is directive and should be preserved
"use strict";
// All above are directives


function foo() {
    
}

"use hello"; // This is not directive and should be preserved
```


### Config

```json
{
  "jsc": {
    "parser": {
      "syntax": "ecmascript"
    },
    "target": "es2022",
    "keepClassNames": true
  },
  "minify": false,
  "isModule": true,
  "module": {
    "type": "commonjs"
  }
}
```


